from datetime import date
from typing import List, Sequence, Tuple

from ledgerlib.aging_bucket import aging_bucket
from ledgerlib.due_date import due_date
from ledgerlib.format_cents import format_cents


def aging_report(invoices: Sequence[Tuple[str, str, int, int]], as_of: str) -> List[str]:
    try:
        ref_date = date.fromisoformat(as_of)
    except ValueError:
        raise ValueError(f"Malformed date: {as_of}")

    buckets = ["current", "1-30", "31-60", "61-90", "90+"]
    totals = {b: 0 for b in buckets}
    grand_total = 0

    for _, inv_date_str, net_days, cents in invoices:
        try:
            inv_date_val = date.fromisoformat(inv_date_str)
            due_date_val = date.fromisoformat(due_date(inv_date_str, net_days))
        except ValueError:
            raise ValueError(f"Malformed date: {inv_date_str}")

        if inv_date_val > ref_date:
            continue

        age = (ref_date - due_date_val).days
        b = aging_bucket(age)
        totals[b] += cents
        grand_total += cents

    lines = []
    for b in buckets:
        lines.append(f"{b:<8}{format_cents(totals[b], '$'):>14}")
    lines.append(f"{'total':<8}{format_cents(grand_total, '$'):>14}")
    return lines
"}}, "messages": []}

